public class InnerEC2FleetReservedCapacityOptionsRequestFactory(Action<Humidifier.EC2.EC2FleetTypes.ReservedCapacityOptionsRequest> factoryAction = null) : SubResourceFactory<Humidifier.EC2.EC2FleetTypes.ReservedCapacityOptionsRequest>
{

    internal InnerEC2FleetReservedCapacityFallbackOptionsRequestFactory ReservedCapacityFallbackOptionsFactory { get; set; }

    internal InnerEC2FleetCapacityReservationTargetRequestFactory CapacityReservationTargetFactory { get; set; }

    protected override Humidifier.EC2.EC2FleetTypes.ReservedCapacityOptionsRequest Create()
    {
        var reservedCapacityOptionsRequestResult = CreateReservedCapacityOptionsRequest();
        factoryAction?.Invoke(reservedCapacityOptionsRequestResult);

        return reservedCapacityOptionsRequestResult;
    }

    private Humidifier.EC2.EC2FleetTypes.ReservedCapacityOptionsRequest CreateReservedCapacityOptionsRequest()
    {
        var reservedCapacityOptionsRequestResult = new Humidifier.EC2.EC2FleetTypes.ReservedCapacityOptionsRequest();

        return reservedCapacityOptionsRequestResult;
    }
    public override void CreateChildren(Humidifier.EC2.EC2FleetTypes.ReservedCapacityOptionsRequest result)
    {
        base.CreateChildren(result);

        result.ReservedCapacityFallbackOptions ??= ReservedCapacityFallbackOptionsFactory?.Build();
        result.CapacityReservationTarget ??= CapacityReservationTargetFactory?.Build();
    }

} // End Of Class

